390	describe('ledger_update_insight', () => {
391	  let globalInsightId: number;
392	  let projectInsightId: number;
393	
394	  beforeEach(async () => {
395	    const g = await addInsight({
396	      scope: 'global',
397	      title: 'Original title',
398	      content: 'Original content.',
399	      category: 'architecture',
400	      tags: ['original'],

401	      confidence: 0.7,
402	    });
403	    globalInsightId = parseResult(g as any).id;
404	
405	    const p = await addInsight({
406	      scope: 'repository',
407	      repository_name: 'repo-b',
408	      title: 'Repository insight',
409	      content: 'Repository content.',
410	      category: 'workflow',
411	      tags: ['workflow'],
412	    });
413	    projectInsightId = parseResult(p as any).id;
414	  });
415	
416	  it('updates title and content of an existing insight', async () => {
417	    const result = await updateInsight({
418	      id: globalInsightId,
419	      title: 'Updated title',
420	      content: 'Updated content.',
421	    });
422	
423	    const data = parseResult(result as any);
424	    expect(data.title).toBe('Updated title');
425	    expect(data.content).toBe('Updated content.');
426	    expect(data.category).toBe('architecture'); // unchanged
427	    expect(data.updated_at).toBeDefined();
428	  });
429	
430	  it('sets updated_at on update', async () => {
431	    const result = await updateInsight({ id: globalInsightId, confidence: 0.9 });
432	    const data = parseResult(result as any);
433	    expect(data.updated_at).toBeDefined();
434	    expect(typeof data.updated_at).toBe('string');
435	  });
436	
437	  it('updates tags array', async () => {
438	    const result = await updateInsight({
439	      id: globalInsightId,
440	      tags: ['new-tag-1', 'new-tag-2'],
441	    });
442	    const data = parseResult(result as any);
443	    expect(data.tags).toEqual(['new-tag-1', 'new-tag-2']);
444	  });
