446	  it('sets superseded_by to mark the insight as outdated', async () => {
447	    // Add a newer insight
448	    const newer = await addInsight({
449	      scope: 'global',
450	      title: 'Newer insight',
451	      content: 'Supersedes the original.',
452	      category: 'architecture',
453	      tags: [],
454	    });
455	    const newerId = parseResult(newer as any).id;
456	
457	    const result = await updateInsight({
458	      id: globalInsightId,
459	      superseded_by: newerId,
460	    });
